const EDGE_TOTAL_0_PROJECT_SQL = `SELECT ?1 AS "repo", ?2 AS "sum" WHERE NOT EXISTS (SELECT 1 FROM "total" n0 WHERE n0."repo" = ?1)`;
const EDGE_TOTAL_0_WRITE_SQL = `INSERT INTO "total" ("repo", "sum") VALUES (?, ?) ON CONFLICT("repo") DO UPDATE SET "sum" = excluded."sum"`;
const EDGE_TOTAL_0_HEAD_COLUMNS: readonly string[] = ["repo", "sum"];
const EDGE_TOTAL_0_KEY_INDICES: readonly number[] = [0];

const EDGE_TOTAL_1_PROJECT_SQL = `SELECT ?1 AS "repo", (b0."sum" + ?2) AS "sum" FROM "__pre_total" b0 WHERE b0."repo" = ?1`;
const EDGE_TOTAL_1_WRITE_SQL = `INSERT INTO "total" ("repo", "sum") VALUES (?, ?) ON CONFLICT("repo") DO UPDATE SET "sum" = excluded."sum"`;
const EDGE_TOTAL_1_HEAD_COLUMNS: readonly string[] = ["repo", "sum"];
const EDGE_TOTAL_1_KEY_INDICES: readonly number[] = [0];

function resolveTotal_0Writes(seam: ISqlSeam, before: Snapshot, arrivals: IArrivalBatch): Observable<readonly SqlStatement[]> {
  const trigger_rows = trigger_occurrences("set", "star_event", before.star_event, arrivals);
  if (trigger_rows.length === 0) return of([]);
  return forkJoin(trigger_rows.map((arrival) => seam.runner.execute(seam.db, { sql: EDGE_TOTAL_0_PROJECT_SQL, args: bind_args(arrival.row) }))).pipe(
    map((results) => {
      const resolved = new Map<string, IRow>();
      for (const result of results) {
        const projected_rows = result.rows.map((row) => EDGE_TOTAL_0_HEAD_COLUMNS.map((column) => row[column] as IRowValue) as IRow);
        for (const projected_row of projected_rows) {
          const key = JSON.stringify(EDGE_TOTAL_0_KEY_INDICES.map((index) => projected_row[index]));
          resolved.set(key, projected_row);
        }
      }
      return [...resolved.values()].map((row): SqlStatement => ({ sql: EDGE_TOTAL_0_WRITE_SQL, args: bind_args(row) }));
    }),
  );
}

